    readouts: (s, c) => { const D = MK.scenes["B5-b"].run(c), e = D[D.length - 1]; return [["Relationship", c.rel], ["Final population 1", f(e[1], 3)], ["Final population 2", f(e[2], 3)]]; },
    story: [{ d: 6, title: "Predation", cap: "Ladybirds eat aphids. As aphids increase, ladybirds have more food and increase; then aphids fall, and so do ladybirds.", set: { rel: "pred" } }, { d: 6, title: "Competition", cap: "Weeds and maize compete for light, water and nutrients. Strong weed competition cuts the maize population.", set: { rel: "comp", k: 1.6 } }, { d: 6, title: "Parasitism", cap: "Ticks feed on cattle: the parasite gains, the host loses blood, weight and milk.", set: { rel: "para", k: 1.2 } }, { d: 6, title: "Mutualism", cap: "Rhizobium bacteria in cowpea root nodules fix nitrogen; the plant feeds the bacteria. Both benefit.", set: { rel: "mut", k: 1 } }],
