    if (wt > 0.85) { const pool = GK.water(w, d, 0x6a7a6a, 0.5); pool.position.y = 0.04; g.add(pool); }
    AK.field(g, "maize", { x0: -4, x1: 4, z0: -2.4, z1: 2.4, dx: 0.6, dz: 0.6, s: 0.55 * (wt > 0.7 ? 0.55 : 1), stage: wt > 0.7 ? 0.45 : 0.85, h, skip: (x, z) => (type === "channel" && Math.abs(z) < 0.4) });
    const rd = clamp(1.2 - wt * 1.2, 0.1, 1.2), rm = AK.std(0xe8dcc0); for (let i = 0; i < 10; i++) { const x = -4 + i * 0.9; g.add(GK.line([[x, 0, d / 2 + 0.04], [x + 0.05, -rd * 0.5, d / 2 + 0.04], [x - 0.04, -rd, d / 2 + 0.04]], 0xe8dcc0, 0.01)); }
